SELECT COUNT(*) FROM payments WHERE created_at::date = CURRENT_DATE;
SELECT COUNT(*) FROM refunds WHERE created_at::date = CURRENT_DATE;
SELECT COUNT(*) FROM shipments WHERE created_at::date = CURRENT_DATE;

SELECT carrier, COUNT(*) AS order_count
FROM shipments
GROUP BY carrier;

SELECT SUM(inventory.on_hand) AS total_stock
FROM inventory
JOIN products ON inventory.product_id = products.id
WHERE products.category_id = (
    SELECT id FROM categories WHERE name = 'Electronics'
);

SELECT email
FROM customers
WHERE segment = 'VIP';

SELECT AVG(CAST(rating AS numeric)) AS average_delivery_rating
FROM (
  SELECT CAST(value AS integer) AS rating
  FROM shop_settings
  WHERE key = 'delivery_rating'
) AS ratings;
